"""Generic data runtime for this research repository (generated by TerraKernel).

All behaviour is driven by the configuration files in ``config/``, which TerraKernel
compiled from the documentation in ``sources/``:

- ``datasets.yaml``: for every data file, its time column, timestamp convention,
  timezone, resolution, and the unit of each value column (with provenance).
- ``conventions.yaml``: the canonical unit per quantity and the canonical timestamp
  convention used by every function here.
- ``parameters.yaml``: values that change on documented dates (for example a capacity),
  and whether an interval uses the value valid at its start or end.

Functions return data already converted to the canonical units and timestamp
convention, so analyses never have to re-derive these rules. Missing values are kept as
NaN; use ``common_valid_sample`` to select rows where every series is present.
Only pandas, numpy and PyYAML are required.
"""

from __future__ import annotations

import functools
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd
import yaml
from research_tools._units import canonical_unit, conversion

PACKAGE_DIR = Path(__file__).resolve().parent
CONFIG_DIR = PACKAGE_DIR / "config"
REPO_ROOT = PACKAGE_DIR.parents[1]
SOURCES_DIR = REPO_ROOT / "sources"

__all__ = [
    "list_datasets", "dataset_info", "load_dataset", "load_series", "load_array", "common_valid_sample",
    "parameter_series", "convert_units",
]


class DataSemanticsError(ValueError):
    """Raised when data cannot be used safely because a documented rule is missing or violated."""


@functools.cache
def _config(name: str) -> dict[str, Any]:
    path = CONFIG_DIR / f"{name}.yaml"
    if not path.exists():
        return {}
    return yaml.safe_load(path.read_text(encoding="utf-8")) or {}


def _datasets() -> dict[str, dict[str, Any]]:
    return {d["name"]: d for d in _config("datasets").get("datasets", [])}


def _conventions() -> dict[str, Any]:
    return _config("conventions")


def _canonical_unit(quantity: str) -> str | None:
    for u in _conventions().get("canonical_units", []):
        if u["quantity"] == quantity:
            return u["unit"]
    return None


def list_datasets() -> list[str]:
    """Names of all configured datasets (use them with ``load_dataset``)."""
    return sorted(_datasets())


def dataset_info(name: str) -> dict[str, Any]:
    """Configuration of one dataset: file, columns, units, timestamp convention, provenance and open issues."""
    try:
        return dict(_datasets()[name])
    except KeyError:
        raise KeyError(f"unknown dataset {name!r}; available: {', '.join(list_datasets())}") from None


def _offset(resolution: str | None) -> pd.Timedelta:
    if not resolution:
        raise DataSemanticsError("the dataset resolution is not documented, so timestamps cannot be shifted safely")
    return pd.Timedelta(pd.tseries.frequencies.to_offset(resolution))


def _parse_time(values: pd.Series, timezone: str | None) -> pd.DatetimeIndex:
    parsed = pd.to_datetime(values, utc=False, format="mixed")
    idx = pd.DatetimeIndex(parsed)
    if idx.tz is None:
        if not timezone:
            raise DataSemanticsError("timestamps have no timezone and the dataset timezone is not documented")
        idx = idx.tz_localize(timezone)
    return idx.tz_convert("UTC")


def load_dataset(name: str, raw: bool = False) -> pd.DataFrame:
    """Load a dataset with its time index and value columns in canonical form.

    - The index is UTC and follows the canonical timestamp convention (for example an
      interval-beginning file is shifted by one resolution step to interval-ending).
    - Every value column is converted to the canonical unit of its quantity.
    - Missing values stay NaN.

    ``raw=True`` returns the file as read, without any conversion.
    ``df.attrs["terrakernel"]`` records every transformation applied.
    """
    cfg = dataset_info(name)
    if cfg.get("format") == "netcdf":
        raise DataSemanticsError(f"{name} is gridded NetCDF data; use load_array({name!r}, variable)")
    df = _read_table(cfg)
    if raw:
        return df
    applied: list[str] = []
    tcol = cfg.get("time_column")
    if tcol:
        idx = _parse_time(df[tcol], cfg.get("timezone"))
        target = _conventions().get("canonical_time_convention", "interval_ending")
        conv = cfg.get("time_convention", "unknown")
        if conv == "unknown":
            raise DataSemanticsError(f"{name}: the timestamp convention of {cfg['file']} is not documented")
        if conv != target and "instant" not in (conv, target):
            step = _offset(cfg.get("resolution"))
            idx = idx + step if (conv, target) == ("interval_beginning", "interval_ending") else idx - step
            applied.append(f"timestamps shifted from {conv} to {target} by {step}")
        df = df.drop(columns=[tcol])
        df.index = idx.rename("timestamp")
    units: dict[str, str] = {}
    for col in cfg.get("value_columns", []):
        c, unit, quantity = col["column"], col.get("unit"), col.get("quantity")
        target = _canonical_unit(quantity) if quantity else None
        if unit is None:
            units[c] = "unknown"
            applied.append(f"{c}: unit not documented, values left unconverted")
            continue
        if target and canonical_unit(unit) != canonical_unit(target):
            scale, offset = conversion(unit, target)
            df[c] = df[c].astype(float) * scale + offset
            applied.append(f"{c}: converted {unit} -> {target}")
            units[c] = target
        else:
            units[c] = unit
    keep = [c["column"] for c in cfg.get("value_columns", [])] or list(df.columns)
    df = df[keep].sort_index()
    if df.index.has_duplicates:
        raise DataSemanticsError(f"{name}: duplicate timestamps after conversion")
    df.attrs["terrakernel"] = {"dataset": name, "file": cfg["file"], "units": units, "applied": applied,
                               "missing": {c: int(df[c].isna().sum()) for c in keep}}
    return df


def _read_table(cfg: dict[str, Any]) -> pd.DataFrame:
    path = SOURCES_DIR / cfg["file"]
    suffix = path.suffix.lower()
    if suffix in (".xlsx", ".xlsm"):
        return pd.read_excel(path, sheet_name=cfg.get("sheet") or 0)
    if suffix == ".parquet":
        return pd.read_parquet(path)
    if suffix == ".tsv":
        return pd.read_csv(path, sep="\t")
    return pd.read_csv(path, sep=cfg.get("separator") or None, engine="python") if cfg.get("separator") else pd.read_csv(path)


def load_array(name: str, variable: str):
    """Load one variable of a NetCDF dataset as an ``xarray.DataArray`` in its canonical unit.

    Values are converted to the canonical unit of the variable's quantity; the timestamp
    convention of the time coordinate is recorded in ``attrs["terrakernel"]`` (gridded data is
    not shifted automatically). Requires ``xarray`` and ``netCDF4``.
    """
    import xarray as xr

    cfg = dataset_info(name)
    col = next((c for c in cfg.get("value_columns", []) if c["column"] == variable), None)
    if col is None:
        raise KeyError(f"{variable!r} is not a configured variable of {name}")
    with xr.open_dataset(SOURCES_DIR / cfg["file"]) as ds:
        da = ds[variable].load()
    applied: list[str] = []
    unit, quantity = col.get("unit"), col.get("quantity")
    target = _canonical_unit(quantity) if quantity else None
    if unit and target and canonical_unit(unit) != canonical_unit(target):
        scale, offset = conversion(unit, target)
        da = da * scale + offset
        applied.append(f"{variable}: converted {unit} -> {target}")
        unit = target
    da.attrs["terrakernel"] = {"dataset": name, "variable": variable, "unit": unit or "unknown", "applied": applied,
                               "time_convention": cfg.get("time_convention", "unknown")}
    return da


def load_series(name: str, column: str | None = None) -> pd.Series:
    """Load one value column of a dataset as a canonical Series (see ``load_dataset``)."""
    df = load_dataset(name)
    cols = list(df.columns)
    if column is None:
        if len(cols) != 1:
            raise ValueError(f"{name} has several value columns {cols}; pass column=")
        column = cols[0]
    s = df[column].rename(f"{name}.{column}")
    s.attrs["terrakernel"] = {**df.attrs.get("terrakernel", {}), "column": column,
                              "unit": df.attrs.get("terrakernel", {}).get("units", {}).get(column)}
    return s


def common_valid_sample(*series: pd.Series, **named: pd.Series) -> pd.DataFrame:
    """Align series on their timestamps and keep only rows where every series has a value.

    Nothing is imputed. ``result.attrs["terrakernel"]`` reports how many rows each input
    lost and the final number of rows.
    """
    items: dict[str, pd.Series] = {}
    for s in series:
        items[str(s.name) if s.name is not None else f"s{len(items)}"] = s
    items.update(named)
    if len(items) < 2:
        raise ValueError("common_valid_sample needs at least two series")
    df = pd.concat(items, axis=1, join="outer", sort=True)
    before = {k: int(v.notna().sum()) for k, v in items.items()}
    out = df.dropna(how="any")
    out.attrs["terrakernel"] = {
        "rows": len(out), "union_rows": len(df), "valid_rows_per_input": before,
        "dropped_per_input": {k: int(df[k].isna().sum()) for k in items},
    }
    return out


def parameter_series(name: str, index: pd.DatetimeIndex | pd.Series | pd.DataFrame,
                     resolution: str | None = None) -> pd.Series:
    """Value of a time-varying parameter for every timestamp of ``index``.

    The lookup point follows ``parameters.yaml``: for ``interval_start`` the value valid
    at the beginning of each interval is used (with interval-ending timestamps that is
    ``t - resolution``); ``interval_end`` uses ``t`` itself.
    """
    params = {p["name"]: p for p in _config("parameters").get("parameters", [])}
    if name not in params:
        raise KeyError(f"unknown parameter {name!r}; available: {', '.join(sorted(params))}")
    p = params[name]
    if isinstance(index, pd.Series | pd.DataFrame):
        index = index.index
    idx = pd.DatetimeIndex(index)
    if idx.tz is None:
        raise DataSemanticsError("parameter lookup needs timezone-aware timestamps")
    lookup = p.get("lookup", "unknown")
    convention = _conventions().get("canonical_time_convention", "interval_ending")
    t = idx
    if lookup in ("interval_start", "interval_end") and convention != "instant":
        if resolution is None:
            diffs = idx.to_series().diff().dropna()
            if diffs.empty:
                raise DataSemanticsError("cannot infer the resolution from a single timestamp; pass resolution=")
            step = diffs.mode().iloc[0]
        else:
            step = _offset(resolution)
        if lookup == "interval_start" and convention == "interval_ending":
            t = idx - step
        elif lookup == "interval_end" and convention == "interval_beginning":
            t = idx + step
    elif lookup == "unknown":
        raise DataSemanticsError(f"{name}: the materials do not say whether an interval uses the value at its start "
                                 "or its end")
    sched = sorted(p["schedule"], key=lambda e: pd.Timestamp(e["valid_from"]))
    starts = pd.DatetimeIndex([pd.Timestamp(e["valid_from"]) for e in sched]).tz_convert("UTC")
    values = np.array([float(e["value"]) for e in sched])
    pos = starts.searchsorted(t, side="right") - 1
    if (pos < 0).any():
        raise DataSemanticsError(f"{name}: no value is documented before {t[pos < 0][0]}")
    out = pd.Series(values[pos], index=idx, name=name)
    out.attrs["terrakernel"] = {"unit": p.get("unit"), "lookup": lookup}
    return out


def convert_units(values: Any, from_unit: str, to_unit: str) -> Any:
    """Convert numbers, arrays or Series between units of the same dimension (e.g. kW -> MW)."""
    scale, offset = conversion(from_unit, to_unit)
    return values * scale + offset
